import sys
values = list(map(int, sys.stdin.read().split()))
s, n = values[:2]
rack, draw = values[2:2 + s], values[2 + s:]

def descents():
    return sum(a > b for a, b in zip(rack, rack[1:]))

bad = descents()
for x in draw:
    if bad == 0:
        break
    slot = None
    # Rule priority is global: exhaust a rule before trying the next one.
    for i in range(1, s):
        if x == rack[i] - 1:
            slot = i - 1
            break
    if slot is None:
        for i in range(s - 1):
            if x == rack[i] + 1:
                slot = i + 1
                break
    if slot is None:
        for i in range(1, s - 1):
            if not rack[i - 1] < rack[i] < rack[i + 1] and rack[i - 1] < x < rack[i + 1]:
                slot = i
                break
    if slot is None and s > 1 and x < rack[1] < rack[0]:
        slot = 0
    if slot is None and s > 1 and x > rack[-2] > rack[-1]:
        slot = s - 1
    if slot is not None:
        # Only the two edges next to the replaced slot can change.
        edges = range(max(0, slot - 1), min(s - 1, slot + 1))
        bad -= sum(rack[i] > rack[i + 1] for i in edges)
        rack[slot] = x
        bad += sum(rack[i] > rack[i + 1] for i in edges)

if bad:
    print(-bad)
else:
    bonus, run = 0, 1
    for a, b in zip(rack, rack[1:]):
        if b == a + 1:
            run += 1
        else:
            if run >= 3:
                bonus += 5 * run
            run = 1
    if run >= 3:
        bonus += 5 * run
    print(sum(rack) + bonus)
